@Test
public final void testGetPartition() {
    Tuple tuple1 = new VTuple(3);
    tuple1.put(new Datum[] { DatumFactory.createInt4(1), DatumFactory.createInt4(2), DatumFactory.createInt4(3) });
    Tuple tuple2 = new VTuple(3);
    tuple2.put(new Datum[] { DatumFactory.createInt4(1), DatumFactory.createInt4(2), DatumFactory.createInt4(4) });
    Tuple tuple3 = new VTuple(3);
