@Test
public void testGetTablesWithPattern() throws Exception {
    String connUri = TestTajoJdbc.buildConnectionUri(tajoMasterAddress.getHostName(), tajoMasterAddress.getPort(), TajoConstants.DEFAULT_DATABASE_NAME);
    Connection conn = DriverManager.getConnection(connUri);
    Map<String, List<String>> tables = new HashMap<String, List<String>>();
    assertDatabaseNotExists("db_1");
    executeString("CREATE DATABASE db_1");
    assertDatabaseExists("db_1");
    for (int i = 0; i < 3; i++) {
        String tableName = "tb_" + i;
        TUtil.putToNestedList(tables, "db_1", tableName);
        executeString("CREATE TABLE db_1." + tableName + " (age int)");
    }
    for (int i = 0; i < 3; i++) {
        String tableName = "table_" + i + "_ptn";
        TUtil.putToNestedList(tables, "db_1", tableName);
        executeString("CREATE TABLE db_1." + tableName + " (age int)");
    }
    assertDatabaseNotExists("db_2");
    executeString("CREATE DATABASE db_2");
    assertDatabaseExists("db_2");
    for (int i = 0; i < 3; i++) {
        String tableName = "tb_" + i;
        TUtil.putToNestedList(tables, "db_2", tableName);
        executeString("CREATE TABLE db_2." + tableName + " (age int)");
    }
    for (int i = 0; i < 3; i++) {
        String tableName = "table_" + i + "_ptn";
        TUtil.putToNestedList(tables, "db_2", tableName);
        executeString("CREATE TABLE db_2." + tableName + " (age int)");
    }
    // all wildcard test
    Set<String> tableList = Sets.newHashSet(getListFromResultSet(conn.getMetaData().getTables("db_2", null, "%", null), "TABLE_NAME"));
    assertEquals(Sets.newHashSet(tables.get("db_2")), tableList);
    // leading wildcard test
    tableList = Sets.newHashSet(getListFromResultSet(conn.getMetaData().getTables("db_2", null, "%_ptn", null), "TABLE_NAME"));
    assertEquals(Sets.newHashSet("table_0_ptn", "table_1_ptn", "table_2_ptn"), tableList);
    // tailing wildcard test
    tableList = Sets.newHashSet(getListFromResultSet(conn.getMetaData().getTables("db_2", null, "tb_%", null), "TABLE_NAME"));
    assertEquals(Sets.newHashSet("tb_0", "tb_1", "tb_2"), tableList);
    ResultSet resultSet = conn.getMetaData().getTables(null, null, "tb\\_%", null);
    int i = 0;
    while (resultSet.next()) {
        tables.get(resultSet.getString("TABLE_CAT")).contains(resultSet.getString("TABLE_NAME"));
        i++;
    }
    assertEquals(6, i);
    executeString("DROP DATABASE db_1");
    executeString("DROP DATABASE db_2");
}

@Test
public void testGetColumnsWithPattern() throws Exception {
    if (!testingCluster.isHCatalogStoreRunning()) {
        String connUri = TestTajoJdbc.buildConnectionUri(tajoMasterAddress.getHostName(), tajoMasterAddress.getPort(), TajoConstants.DEFAULT_DATABASE_NAME);
        Connection conn = DriverManager.getConnection(connUri);
        // Below creates the following 12 tables
        // db<i>.tb<j>, i = {1,2}, 0 <= j < 2
        // db<i>.table_<j>, i = {1,2}, 0 <= j < 2
        Map<String, List<String>> tables = new HashMap<String, List<String>>();
        for (int j = 1; j <= 2; j++) {
            String dbName = "db" + j;
            assertDatabaseNotExists(dbName);
            executeString("CREATE DATABASE " + dbName).close();
            assertDatabaseExists(dbName);
            for (int i = 3; i < 6; i++) {
                String tableName = "tb" + i;
                if (i % 2 == 0) {
                    tableName = tableName.toUpperCase();
                }
                TUtil.putToNestedList(tables, dbName, tableName);
                executeString("CREATE TABLE " + dbName + "." + CatalogUtil.denormalizeIdentifier(tableName) + " (" + getTestColName(dbName, tableName, 1) + ") PARTITION BY COLUMN (" + getTestColName(dbName, tableName, 2) + ")").close();
                assertTableExists(dbName + "." + tableName);
            }
            for (int i = 3; i < 6; i++) {
                String tableName = "table" + i;
                if (i % 2 == 0) {
                    tableName = tableName.toUpperCase();
                }
                TUtil.putToNestedList(tables, dbName, tableName);
                executeString("CREATE TABLE " + dbName + "." + CatalogUtil.denormalizeIdentifier(tableName) + " (" + getTestColName(dbName, tableName, 1) + ") PARTITION BY COLUMN (" + getTestColName(dbName, tableName, 2) + ")").close();
                assertTableExists(dbName + "." + tableName);
            }
        }
        // all wildcard test on columns
        Set<String> columnList = Sets.newHashSet(getListFromResultSet(conn.getMetaData().getColumns("db2", null, "tb3", "%"), "COLUMN_NAME"));
        assertEquals(Sets.newHashSet("db2_tb3_col", "db2_tb3_COL"), columnList);
        // tailing wildcard + case sensitive test on columns
        columnList = Sets.newHashSet(getListFromResultSet(conn.getMetaData().getColumns("db2", null, "tb3", "%col"), "COLUMN_NAME"));
        assertEquals(Sets.newHashSet("db2_tb3_col"), columnList);
        columnList = Sets.newHashSet(getListFromResultSet(conn.getMetaData().getColumns("db2", null, "tb3", "%COL"), "COLUMN_NAME"));
        assertEquals(Sets.newHashSet("db2_tb3_COL"), columnList);
        // tailing wildcard test on columns
        columnList = Sets.newHashSet(getListFromResultSet(conn.getMetaData().getColumns("db2", null, "tb3", "db2\\_tb3\\_%"), "COLUMN_NAME"));
        assertEquals(Sets.newHashSet("db2_tb3_col", "db2_tb3_COL"), columnList);
        columnList = Sets.newHashSet(getListFromResultSet(conn.getMetaData().getColumns("db2", null, "%", "db2\\_tb3\\_%"), "COLUMN_NAME"));
        assertEquals(Sets.newHashSet("db2_tb3_col", "db2_tb3_COL"), columnList);
        // leading wildcard test on tables
        columnList = Sets.newHashSet(getListFromResultSet(conn.getMetaData().getColumns("db1", null, "%3", "%"), "COLUMN_NAME"));
        assertEquals(Sets.newHashSet("db1_tb3_col", "db1_tb3_COL", "db1_table3_col", "db1_table3_COL"), columnList);
        columnList = Sets.newHashSet(getListFromResultSet(conn.getMetaData().getColumns("db2", null, "%3", "%"), "COLUMN_NAME"));
        assertEquals(Sets.newHashSet("db2_tb3_col", "db2_tb3_COL", "db2_table3_col", "db2_table3_COL"), columnList);
        // tailing wildcard + case sensitive test on tables
        columnList = Sets.newHashSet(getListFromResultSet(conn.getMetaData().getColumns("db2", null, "TABLE%", "%"), "COLUMN_NAME"));
        assertEquals(Sets.newHashSet("db2_TABLE4_col", "db2_TABLE4_COL"), columnList);
        columnList = Sets.newHashSet(getListFromResultSet(conn.getMetaData().getColumns("db2", null, "TABLE4", "%"), "COLUMN_NAME"));
        assertEquals(Sets.newHashSet("db2_TABLE4_col", "db2_TABLE4_COL"), columnList);
        // tailing wildcard test on tables
        columnList = Sets.newHashSet(getListFromResultSet(conn.getMetaData().getColumns("db2", null, "table%", "%"), "COLUMN_NAME"));
        assertEquals(Sets.newHashSet("db2_table3_col", "db2_table3_COL", "db2_table5_col", "db2_table5_COL"), columnList);
        // wildcard test on database
        columnList = Sets.newHashSet(getListFromResultSet(conn.getMetaData().getColumns(null, null, "%3", "db1_tb3%"), "COLUMN_NAME"));
        assertEquals(Sets.newHashSet("db1_tb3_col", "db1_tb3_COL"), columnList);
        executeString("DROP DATABASE db1");
        executeString("DROP DATABASE db2");
    }
}

