@Test
public void testMultipleConnectionsSequentialClose() throws Exception {
    String connUri = buildConnectionUri(tajoMasterAddress.getHostName(), tajoMasterAddress.getPort(), DEFAULT_DATABASE_NAME);
    Connection[] conns = new Connection[2];
    conns[0] = DriverManager.getConnection(connUri);
    conns[1] = DriverManager.getConnection(connUri);
    try {
        for (int i = 0; i < conns.length; i++) {
            Statement stmt = null;
            ResultSet res = null;
            try {
                stmt = conns[i].createStatement();
                res = stmt.executeQuery("select l_returnflag, l_linestatus, count(*) as count_order from lineitem " + "group by l_returnflag, l_linestatus order by l_returnflag, l_linestatus");
                try {
                    Map<String, Integer> result = Maps.newHashMap();
                    result.put("NO", 3);
                    result.put("RF", 2);
                    assertNotNull(res);
                    assertTrue(res.next());
                    assertTrue(result.get(res.getString(1) + res.getString(2)) == res.getInt(3));
                    assertTrue(res.next());
                    assertTrue(result.get(res.getString(1) + res.getString(2)) == res.getInt(3));
                    assertFalse(res.next());
                    ResultSetMetaData rsmd = res.getMetaData();
                    assertEquals(3, rsmd.getColumnCount());
                    assertEquals("l_returnflag", rsmd.getColumnName(1));
                    assertEquals("l_linestatus", rsmd.getColumnName(2));
                    assertEquals("count_order", rsmd.getColumnName(3));
                } finally {
                    res.close();
                }
            } finally {
                if (res != null) {
                    res.close();
                }
                if (stmt != null) {
                    stmt.close();
                }
                conns[i].close();
            }
        }
    } finally {
        if (!conns[0].isClosed()) {
            assertTrue(conns[0].isValid(100));
            conns[0].close();
            assertFalse(conns[0].isValid(100));
        }
        if (!conns[1].isClosed()) {
            assertTrue(conns[1].isValid(100));
            conns[1].close();
            assertFalse(conns[1].isValid(100));
        }
    }
}

