        QueryId queryId = QueryIdFactory.newQueryId(queryIdTime, 2);
        int requiredContainers = 60;
        int numAllocatedContainers = 0;
        int loopCount = 0;
        while (true) {
            WorkerResourceAllocationRequest request = WorkerResourceAllocationRequest.newBuilder().setResourceRequestPriority(ResourceRequestPriority.MEMORY).setNumContainers(requiredContainers - numAllocatedContainers).setQueryId(queryId.getProto()).setMaxDiskSlotPerContainer(diskSlots).setMinDiskSlotPerContainer(diskSlots).setMinMemoryMBPerContainer(minMemory).setMaxMemoryMBPerContainer(maxMemory).build();
            final CountDownLatch barrier = new CountDownLatch(1);
            RpcCallback<WorkerResourceAllocationResponse> callBack = new RpcCallback<WorkerResourceAllocationResponse>() {

