                assertEquals(0.0f, resource.getUsedDiskSlots(), 0);
                assertEquals(workerDiskSlots, resource.getAvailableDiskSlots(), 0);
            }
            loopCount++;
            if (loopCount == 2) {
                assertEquals(requiredContainers, numAllocatedContainers);
