    seedTuple.put(new Datum[] { // 0
    DatumFactory.createBool(true), // 1
    DatumFactory.createBit((byte) 0x99), // 2
    DatumFactory.createChar("hyunsik"), // 3
    DatumFactory.createInt2((short) 17), // 4
    DatumFactory.createInt4(59), // 5
    DatumFactory.createInt8(23l), // 6
    DatumFactory.createFloat4(77.9f), // 7
    DatumFactory.createFloat8(271.9f), // 8
    DatumFactory.createText("hyunsik"), // 9
    DatumFactory.createBlob("hyunsik".getBytes()), // 10
    DatumFactory.createInet4("192.168.0.1"), // 11
    NullDatum.get(), // 12
    factory.createDatum(queryid.getProto()) });
    // Making tuples with different null column positions
    Tuple tuple;
    for (int i = 0; i < 13; i++) {
        tuple = new VTuple(13);
        for (int j = 0; j < 13; j++) {
            if (i == j) {
                // i'th column will have NULL value
                tuple.put(j, NullDatum.get());
            } else {
                tuple.put(j, seedTuple.get(j));
            }
        }
        appender.addTuple(tuple);
    }
    appender.flush();
    appender.close();
    FileStatus status = fs.getFileStatus(tablePath);
    FileFragment fragment = new FileFragment("table", tablePath, 0, status.getLen());
    Scanner scanner = StorageManagerFactory.getStorageManager(conf).getScanner(meta, schema, fragment);
    scanner.init();
    Tuple retrieved;
    int i = 0;
    while ((retrieved = scanner.next()) != null) {
        assertEquals(13, retrieved.size());
        for (int j = 0; j < 13; j++) {
            if (i == j) {
                assertEquals(NullDatum.get(), retrieved.get(j));
            } else {
                assertEquals(seedTuple.get(j), retrieved.get(j));
            }
        }
        i++;
    }
    scanner.close();
}

